<script lang="ts">
import {Component, Prop} from 'vue-property-decorator'
import {PortalVueBase} from '@/view/PortalVueBase'
import {ExperienceItem} from '@/model/Data/ProfileData'
import ExperienceBody from '@/view/Experience/ExperienceBody.vue'

@Component({components: {ExperienceBody}})
export default class ExperienceTimeline extends PortalVueBase {
